public class IteratorUtils_collatedIterator_TriageGen1Test {

    @Test
    public void testCollatedIteratorWithIntegers() {
        // Arrange
        Comparator<Integer> comparator = Integer::compareTo;
        List<Integer> list1 = Arrays.asList(1, 3, 5);
        List<Integer> list2 = Arrays.asList(2, 4, 6);
        Iterator<Integer> it1 = list1.iterator();
        Iterator<Integer> it2 = list2.iterator();

        // Act
        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, it1, it2);

        // Assert
        assertTrue(result.hasNext());
        assertEquals(Integer.valueOf(1), result.next());
        assertEquals(Integer.valueOf(2), result.next());
        assertEquals(Integer.valueOf(3), result.next());
        assertEquals(Integer.valueOf(4), result.next());
        assertEquals(Integer.valueOf(5), result.next());
        assertEquals(Integer.valueOf(6), result.next());
        assertFalse(result.hasNext());
    }

    @Test
    public void testCollatedIteratorWithDifferentSizes() {
        // Arrange
        Comparator<Integer> comparator = Integer::compareTo;
        List<Integer> list1 = Arrays.asList(1, 10);
        List<Integer> list2 = Arrays.asList(2, 3, 4, 5);
        Iterator<Integer> it1 = list1.iterator();
        Iterator<Integer> it2 = list2.iterator();

        // Act
        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, it1, it2);

        // Assert
        assertEquals(Integer.valueOf(1), result.next());
        assertEquals(Integer.valueOf(2), result.next());
        assertEquals(Integer.valueOf(3), result.next());
        assertEquals(Integer.valueOf(4), result.next());
        assertEquals(Integer.valueOf(5), result.next());
        assertEquals(Integer.valueOf(10), result.next());
        assertFalse(result.hasNext());
    }

    @Test
    public void testCollatedIteratorWithEmptyIterators() {
        // Arrange
        Comparator<String> comparator = String::compareTo;
        Iterator<String> it1 = Arrays.asList("a").iterator();
        Iterator<String> it2 = Arrays.asList().iterator();

        // Act
        Iterator<String> result = IteratorUtils.collatedIterator(comparator, it1, it2);

        // Assert
        assertEquals(Integer.valueOf(1), IteratorUtils.toList(result).size());
        assertEquals("a", IteratorUtils.toList(result).get(0));
    }

    @Test
    public void testCollatedIteratorWithStrings() {
        // Arrange
        Comparator<String> comparator = Comparator.naturalOrder();
        Iterator<String> it1 = Arrays.asList("apple", "cherry").iterator();
        Iterator<String> it2 = Arrays.asList("banana", "date").iterator();

        // Act
        Iterator<String> result = IteratorUtils.collatedIterator(comparator, it1, it2);

        // Assert
        List<String> expected = Arrays.asList("apple", "banana", "cherry", "date");
        List<String> actual = IteratorUtils.toList(result);
        assertEquals(expected, actual);
    }

    @Test
    public void testCollatedIteratorWithNullComparator() {
        // Note: The implementation passes the comparator directly to CollatingIterator.
        // If the comparator is null, CollatingIterator.next() will likely throw NullPointerException 
        // when it tries to use it. This tests the behavior of the wrapper method.

        Iterator<Integer> it1 = Arrays.asList(1).iterator();
        Iterator<Integer> it2 = Arrays.asList(2).iterator();

        try {
            Iterator<Integer> result = IteratorUtils.collatedIterator(null, it1, it2);
            result.next();
            // If we reach here, it means the implementation doesn't check for null immediately.
            // But the first call to next() should trigger the error.
        } catch (NullPointerException e) {
            // Expected behavior if CollatingIterator uses the comparator
        }
    }
